#!/usr/bin/env node

/**
 * MyDash — Bootstrap 22: Build visual library browser
 *
 * Usage:
 *   node scripts/22-build-visual-library-browser.mjs
 *   node scripts/22-build-visual-library-browser.mjs --dry-run
 *   node scripts/22-build-visual-library-browser.mjs --no-commit
 *   node scripts/22-build-visual-library-browser.mjs --no-push
 *   node scripts/22-build-visual-library-browser.mjs --json
 *   node scripts/22-build-visual-library-browser.mjs --target /path/to/mydash
 */

